// src/lib/images.ts
// Reads the pre-built image manifest (generated by scripts/optimize-images.mjs)
// and resolves responsive AVIF/WebP variants, LQIP placeholders, and OG covers.
import fs from 'node:fs';
import path from 'node:path';
import { getPath } from '../../site.config';

export interface ImageVariant {
  w: number;
  src: string;
}

export interface OptimizedImageInfo {
  type?: 'raster' | 'animated' | 'svg';
  filename: string;
  sourcePath: string;
  optimizedUrl: string;
  fullAvifUrl?: string;
  width: number;
  height: number;
  format: string;
  sizeBytes: number;
  isOversized: boolean;
  variants?: {
    avif: ImageVariant[];
    webp: ImageVariant[];
  };
  placeholder?: string;
}

const imageRegistry = new Map<string, OptimizedImageInfo>();
let hasLoaded = false;

function loadManifest(): Map<string, OptimizedImageInfo> {
  if (hasLoaded && imageRegistry.size > 0) {
    return imageRegistry;
  }

  const manifestPath = path.resolve(process.cwd(), 'src', 'generated', 'images-manifest.json');
  if (!fs.existsSync(manifestPath)) {
    return imageRegistry;
  }

  try {
    const raw = JSON.parse(fs.readFileSync(manifestPath, 'utf-8')) as Record<string, any>;
    for (const [key, entry] of Object.entries(raw)) {
      const avif = (entry.variants?.avif || []).map((v: ImageVariant) => ({
        w: v.w,
        src: getPath(v.src),
      }));
      const webp = (entry.variants?.webp || []).map((v: ImageVariant) => ({
        w: v.w,
        src: getPath(v.src),
      }));

      const info: OptimizedImageInfo = {
        type: entry.type || 'raster',
        filename: entry.filename,
        sourcePath: entry.sourcePath,
        optimizedUrl: getPath(entry.src || entry.optimizedUrl),
        fullAvifUrl: entry.fullAvifUrl ? getPath(entry.fullAvifUrl) : getPath(entry.src || entry.optimizedUrl),
        width: entry.width,
        height: entry.height,
        format: entry.format || 'webp',
        sizeBytes: entry.sizeBytes || 0,
        isOversized: Boolean(entry.isOversized),
        variants: { avif, webp },
        placeholder: entry.placeholder,
      };

      imageRegistry.set(key.toLowerCase(), info);
    }
    hasLoaded = true;
  } catch (err: any) {
    console.error(`[Image Error] Failed to read images-manifest.json: ${err.message}`);
  }

  return imageRegistry;
}

/**
 * Loads the pre-generated image manifest into memory.
 */
export async function scanAndOptimizeImages(): Promise<Map<string, OptimizedImageInfo>> {
  return loadManifest();
}

/**
 * Resolves an image reference (e.g. "my-image.png" or "attachments/my-image.png").
 * If missing, reports a warning and returns null.
 */
export function resolveImage(imageRef: string, articleId: string = ''): OptimizedImageInfo | null {
  loadManifest();
  try {
    imageRef = decodeURIComponent(imageRef);
  } catch {}
  const normalizedRef = imageRef.replace(/\\/g, '/').replace(/^\.\//, '').trim().toLowerCase();
  const cleanName = path.basename(normalizedRef).trim().toLowerCase();
  const info = imageRegistry.get(normalizedRef) || imageRegistry.get(cleanName);

  if (!info) {
    console.warn(`[Image Warning] Missing image "${imageRef}" referenced in article "${articleId}".`);
    return null;
  }

  return info;
}

/**
 * Returns all unique registered images.
 */
export function getAllImages(): OptimizedImageInfo[] {
  loadManifest();
  const unique = new Map<string, OptimizedImageInfo>();
  for (const info of imageRegistry.values()) {
    unique.set(info.sourcePath.toLowerCase(), info);
  }
  return Array.from(unique.values());
}
